mapper.select:
SELECT id, task_id, from_user_id, from_user_name, from_user_department_id, from_user_department_name, status, msg_sent_time, msg_seqid, post_id, post_name, create_time, expired_time, response_time, response_user_id, response_user_name, ignore_time, ignore_user_id, ignore_user_name, track_time, track_user_id, track_user_name, finish_time, finish_user_id, finish_user_name, task_updated_time FROM tb_static_task WHERE create_time >= #{startTime} AND create_time < #{endTime}
AND from_user_department_id IN
#{deptId}
AND (create_time < #{lastTime} OR (create_time = #{lastTime} AND id < #{lastId}))
ORDER BY create_time DESC, id DESC LIMIT #{pageSize}
